def transform(grid):
    h, w = len(grid), len(grid[0])
    sep = 2
    row_groups = []
    start = 0
    for r in range(h):
        if all(v == sep for v in grid[r]):
            if start < r:
                row_groups.append((start, r))
            start = r + 1
    if start < h:
        row_groups.append((start, h))

    col_groups = []
    start = 0
    for c in range(w):
        if all(grid[r][c] == sep for r in range(h)):
            if start < c:
                col_groups.append((start, c))
            start = c + 1
    if start < w:
        col_groups.append((start, w))

    background = next(grid[r][c] for r in range(h) for c in range(w) if grid[r][c] != sep)
    marker = next((grid[r][c] for r in range(h) for c in range(w)
                   if grid[r][c] not in (sep, background)), None)

    out = []
    for r0, r1 in row_groups:
        row = []
        for c0, c1 in col_groups:
            count = sum(grid[r][c] == marker for r in range(r0, r1) for c in range(c0, c1))
            row.append(1 if count == 2 else background)
        out.append(row)
    return out
